
import React, { forwardRef, useEffect, useRef, useState, useMemo } from 'react';
import './PlacaMaisChurrasco.css';

const PlacaMaisChurrasco = forwardRef(({ titulo, precoInicial, precoReal, precoCentavos, dataInicial, dataFinal }, ref) => {

    const tituloRef = useRef(null);
    const containerRef = useRef(null);
    const [fontSize, setFontSize] = useState(100); // tamanho inicial da fonte

      useEffect(() => {
        const ajustarFonte = () => {
          const tituloE1 = tituloRef.current;
          const containerE1 = containerRef.current;

          if (!tituloE1 || !containerE1) return;

          let size = 100;
          tituloE1.style.fontSize = `${size}px`;

          while (
            (tituloE1.scrollHeight - containerE1.clientHeight > 10 ||
            tituloE1.scrollWidth - containerE1.clientWidth > 10) &&
            size > 5
          ) {
            size -= 1;
            tituloE1.style.fontSize = `${size}px`;
          }

          setFontSize(size);
        };

        ajustarFonte();
      }, [titulo]);

     const fontSizeRealChurrasco = useMemo(() => {
            if (!precoReal) return '640px';
            const length = precoReal.toString().length;
            console.log(length);
        
            if (length <= 2) return '600px';   // 1 ou 2 dígitos
            if (length === 3) return '500px';  // 3 dígitos
            if (length === 4) return '400px';  // 4 dígitos
            return '320px';                    // 5 ou mais dígitos
          }, [precoReal]);
          

  return (
    <div ref={ref} className="placa-maischurrasco">
        <span className="sloganMaisChurrasco">MAIS CHURRASCO</span>
        <div className="corpoMaisChurrasco">
          <div
              className="tituloMaisChurrascoContainer"
              ref={containerRef}
              style={{
                width: '100%',
                height: '50mm', // defina altura conforme desejado
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                overflow: 'hidden',
                textAlign: 'center',
                border: '1px dashed red;' /* opcional, para visualizar limites */
              }}
          >
            <span 
              ref={tituloRef}
              className="tituloMaisChurrasco"
              style={{
                fontSize: `${fontSize}px`,
                lineHeight: 1.1,
                wordBreak: 'break-word',
              }}
            >
              {titulo}
            </span>
          </div>
            {(precoInicial && precoInicial !== "-") && <span className='cifraoMaisChurrasco'>&nbsp;De&nbsp;<b>{precoInicial} </b>. Por R$</span>}
            {!precoInicial && <span className='cifraoMaisChurrasco'>&nbsp; R$</span>}
            <div className='precoMaisChurrasco'>

              <span 
                className="precoMaisChurrascoReal"
                style={{ fontSize: fontSizeRealChurrasco }}
              >
                {precoReal} 
              </span>
              <span className="precoMaisChurrascoCentavos">,{precoCentavos}</span>
            </div>    
        </div>
        {dataInicial === dataFinal ? (
            <span className='footerMaisChurrasco'>Oferta válida para o dia {dataFinal}.</span>
          ) : (
            <span className='footerMaisChurrasco'>Oferta válida de {dataInicial} até {dataFinal}.</span>
          )
        }
    </div>
  );
});

export default PlacaMaisChurrasco;